INSERT INTO problem (module_type, category, arena, title, description_markdown, hints_markdown, solution_explanation_markdown, difficulty, tags) VALUES
('MCQ', 'JAVA', 'MCQ', 'HashMap vs HashTable', '# HashMap vs HashTable\n\nWhat is the key difference?\n\nA) HashMap is synchronized\nB) HashTable is synchronized\nC) Both are synchronized\nD) Neither synchronized', 'Hint 1: Thread-safety.\n---\nHint 2: HashTable is legacy.\n---\nHint 3: From Java 1.0.', 'Answer: B\n\nHashTable is synchronized (thread-safe but slower). HashMap is not synchronized (faster but not thread-safe). Use ConcurrentHashMap for concurrent access.', 'EASY', 'java,collections'),
('MCQ', 'JAVA', 'MCQ', 'String Immutability', '# String Immutability\n\nWhy are Strings immutable in Java?\n\nA) Performance only\nB) Security, caching, thread-safety\nC) Memory efficiency only\nD) No good reason', 'Hint 1: Multiple benefits.\n---\nHint 2: String pool.\n---\nHint 3: Security for passwords.', 'Answer: B\n\nStrings are immutable for security (cannot be changed after creation), string pooling (memory efficiency), thread-safety (no synchronization needed), and hashcode caching.', 'MEDIUM', 'java,strings'),
('MCQ', 'JAVA', 'MCQ', 'equals() vs ==', '# equals() vs ==\n\nString s1 = "hello";\nString s2 = "hello";\nString s3 = new String("hello");\n\nWhich is false?\n\nA) s1 == s2\nB) s1.equals(s2)\nC) s1 == s3\nD) s1.equals(s3)', 'Hint 1: String pool.\n---\nHint 2: == checks reference.\n---\nHint 3: new creates new object.', 'Answer: C\n\ns1 and s2 point to same string pool object (==true). s3 is new object (==false). equals() checks content, so all equals() are true.', 'EASY', 'java,strings,operators'),
('MCQ', 'JAVA', 'MCQ', 'ArrayList vs LinkedList', '# ArrayList vs LinkedList\n\nWhen is LinkedList better?\n\nA) Random access\nB) Frequent insertions/deletions in middle\nC) Iteration\nD) Never better', 'Hint 1: Think about operations.\n---\nHint 2: Array shifting vs pointer updates.\n---\nHint 3: O(1) vs O(n).', 'Answer: B\n\nLinkedList is better for frequent insertions/deletions in middle (O(1) vs O(n) for ArrayList). ArrayList is better for random access and iteration.', 'MEDIUM', 'java,collections'),
('MCQ', 'JAVA', 'MCQ', 'final vs finally vs finalize', '# final vs finally vs finalize\n\nWhich is used for cleanup?\n\nA) final\nB) finally\nC) finalize\nD) All three', 'Hint 1: Garbage collection.\n---\nHint 2: Deprecated in Java 9.\n---\nHint 3: Not recommended.', 'Answer: C\n\nfinalize() is called by GC before object destruction (deprecated). finally is for try-catch cleanup. final makes variables/methods/classes immutable/non-overridable.', 'EASY', 'java,keywords');
INSERT INTO problem (module_type, category, arena, title, description_markdown, hints_markdown, solution_explanation_markdown, difficulty, tags) VALUES
('MCQ', 'KOTLIN', 'MCQ', 'Nullable Types', '# Nullable Types\n\nWhich is valid Kotlin?\n\nA) var name: String = null\nB) var name: String? = null\nC) var name: String! = null\nD) var name = null', 'Hint 1: Null safety is key.\n---\nHint 2: ? makes nullable.\n---\nHint 3: ! is not Kotlin syntax.', 'Answer: B\n\nKotlin requires explicit nullable types with ?. Non-nullable types cannot be null. ! is used for assertions, not declarations.', 'EASY', 'kotlin,null-safety'),
('MCQ', 'KOTLIN', 'MCQ', 'Data Classes', '# Data Classes\n\nWhat do data classes provide?\n\nA) equals, hashCode, toString\nB) copy() method\nC) componentN() functions\nD) All of the above', 'Hint 1: Automatic generation.\n---\nHint 2: Multiple features.\n---\nHint 3: Destructuring.', 'Answer: D\n\nData classes auto-generate equals(), hashCode(), toString(), copy(), and component functions for destructuring.', 'EASY', 'kotlin,data-classes');
INSERT INTO problem (module_type, category, arena, title, description_markdown, hints_markdown, solution_explanation_markdown, difficulty, tags) VALUES
('MCQ', 'SPRING_CORE', 'MCQ', 'Bean Scopes', '# Bean Scopes\n\nDefault bean scope?\n\nA) singleton\nB) prototype\nC) request\nD) session', 'Hint 1: Most common.\n---\nHint 2: One instance per container.\n---\nHint 3: First option.', 'Answer: A\n\nDefault scope is singleton - one instance per Spring container. Prototype creates new instance each time bean is requested.', 'EASY', 'spring,beans'),
('MCQ', 'SPRING_BOOT', 'MCQ', 'Auto-configuration', '# Auto-configuration\n\nHow does Spring Boot auto-configure?\n\nA) @EnableAutoConfiguration\nB) META-INF/spring.factories\nC) Conditional annotations\nD) All of the above', 'Hint 1: Multiple mechanisms.\n---\nHint 2: SPI-like discovery.\n---\nHint 3: Conditions check.', 'Answer: D\n\nSpring Boot uses @EnableAutoConfiguration, discovers configurations from spring.factories, and applies them based on @Conditional annotations.', 'MEDIUM', 'spring-boot,autoconfiguration');
INSERT INTO problem (module_type, category, arena, title, description_markdown, hints_markdown, solution_explanation_markdown, difficulty, tags) VALUES
('MCQ', 'JVM', 'MCQ', 'Memory Areas', '# JVM Memory Areas\n\nWhere are objects stored?\n\nA) Stack\nB) Heap\nC) Method Area\nD) PC Register', 'Hint 1: Dynamic allocation.\n---\nHint 2: Shared among threads.\n---\nHint 3: GC operates here.', 'Answer: B\n\nObjects are stored in Heap. Stack stores local variables and method frames. Method Area stores class metadata. PC Register stores current instruction.', 'EASY', 'jvm,memory'),
('MCQ', 'JVM', 'MCQ', 'Garbage Collectors', '# Garbage Collectors\n\nWhich GC is for low latency?\n\nA) Serial GC\nB) Parallel GC\nC) G1 GC\nD) ZGC', 'Hint 1: Modern GC.\n---\nHint 2: Sub-millisecond pauses.\n---\nHint 3) Z prefix.', 'Answer: D\n\nZGC provides sub-millisecond pause times. G1 is low-pause but not as low. Serial/Parallel have higher pauses.', 'HARD', 'jvm,gc');
INSERT INTO problem (module_type, category, arena, title, description_markdown, hints_markdown, solution_explanation_markdown, difficulty, tags) VALUES
('MCQ', 'CONCURRENCY', 'MCQ', 'synchronized vs volatile', '# synchronized vs volatile\n\nWhat does volatile guarantee?\n\nA) Atomicity\nB) Visibility\nC) Ordering\nD) B and C', 'Hint 1: Not atomicity.\n---\nHint 2: Multiple guarantees.\n---\nHint 3: Memory visibility.', 'Answer: D\n\nvolatile guarantees visibility (all threads see latest value) and ordering (happens-before). It does NOT guarantee atomicity for compound operations.', 'MEDIUM', 'java,concurrency'),
('MCQ', 'CONCURRENCY', 'MCQ', 'Thread States', '# Thread States\n\nWhich is NOT a thread state?\n\nA) NEW\nB) RUNNABLE\nC) SLEEPING\nD) TERMINATED', 'Hint 1: Java Thread.State enum.\n---\nHint 2: TIMED_WAITING exists.\n---\nHint 3: Not SLEEPING.', 'Answer: C\n\nStates are: NEW, RUNNABLE, BLOCKED, WAITING, TIMED_WAITING, TERMINATED. SLEEPING is not a state (it''s TIMED_WAITING).', 'EASY', 'java,concurrency,threads');
